windows.css:
#detail{box-sizing:border-box;padding:16px 18px;border-radius:8px;overflow:auto;
  background:rgba(255,255,255,.0512);border:1px solid rgba(255,255,255,.0698)}
body.theme-light #detail{background:#fff;border-color:rgba(0,0,0,.08)}
.dt-name{font-size:20px;font-weight:600;margin-bottom:14px}
.dt-row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid rgba(128,128,128,.15)}
.dt-row span{opacity:.6}
.dt-bar{height:6px;border-radius:3px;background:rgba(128,128,128,.25);margin:16px 0 6px}
.dt-bar i{display:block;height:100%;border-radius:3px;background:#60cdff}
.dt-empty{opacity:.55;padding-top:40px;text-align:center}

events.code:
s := g.Prompt("A new score for " row.name, "Score", row.score)
if IsNumber(s) {
    row.score := Integer(s)
    grid.Refresh()
    ShowPerson(row)
}
